// ============================================
// n8n CODE NODE
// Extract Correct Month + CURRENT Runtime Year
// Production Grade
//
// RULES:
// - ALWAYS use CURRENT runtime year
// - NEVER trust years from brief/timeline
// - If deadline day = 1
//   → use PREVIOUS month
// ============================================

// ============================================
// INPUTS
// ============================================

const timeline =
  $input.first()?.json?.timeline || [];

const deadline =
  $input.first()?.json?.deadline || {};

// ============================================
// CURRENT RUNTIME DATE
// ============================================

const now =
  new Date();

const CURRENT_YEAR =
  now.getFullYear();

// ============================================
// MONTHS
// ============================================

const months = [

  "January",
  "February",
  "March",
  "April",
  "May",
  "June",
  "July",
  "August",
  "September",
  "October",
  "November",
  "December"
];

// ============================================
// HELPERS
// ============================================

function getPreviousMonth(dateObj) {

  const d =
    new Date(dateObj);

  d.setMonth(
    d.getMonth() - 1
  );

  return {
    month:
      months[d.getMonth()],

    // ALWAYS CURRENT YEAR
    year:
      String(CURRENT_YEAR)
  };
}

function extractMonth(text = '') {

  const clean =
    String(text).trim();

  for (const month of months) {

    const regex =
      new RegExp(
        `\\b${month}\\b`,
        'i'
      );

    if (regex.test(clean)) {

      return month;
    }
  }

  return null;
}

// ============================================
// MAIN LOGIC
// ============================================

let foundMonth = null;

// ============================================
// PRIORITY 1:
// deadline.iso_date
// ============================================

if (deadline?.iso_date) {

  const d =
    new Date(deadline.iso_date);

  if (!isNaN(d)) {

    // BUSINESS RULE:
    // If deadline is 1st day
    // use PREVIOUS month

    if (d.getDate() === 1) {

      const prev =
        getPreviousMonth(d);

      foundMonth =
        prev.month;

    } else {

      foundMonth =
        months[d.getMonth()];
    }
  }
}

// ============================================
// PRIORITY 2:
// deadline.raw
// ============================================

if (
  !foundMonth &&
  deadline?.raw
) {

  foundMonth =
    extractMonth(
      deadline.raw
    );
}

// ============================================
// PRIORITY 3:
// timeline
// ============================================

if (!foundMonth) {

  for (const item of timeline) {

    const values = [

      item?.phase,
      item?.date,
      item?.description
    ];

    for (const val of values) {

      if (!val) {
        continue;
      }

      const month =
        extractMonth(val);

      if (month) {

        foundMonth =
          month;

        break;
      }
    }

    if (foundMonth) {
      break;
    }
  }
}

// ============================================
// FINAL FALLBACK
// ============================================

if (!foundMonth) {

  foundMonth =
    months[now.getMonth()];
}

// ============================================
// ALWAYS USE CURRENT YEAR
// ============================================

const foundYear =
  String(CURRENT_YEAR);

// ============================================
// SHEET NAME
// ============================================

const shortYear =
  foundYear.slice(-2);

const sheetName =
  `${foundMonth} ${shortYear}`;

// ============================================
// OUTPUT
// ============================================

return [{
  json: {

    month:
      foundMonth,

    year:
      foundYear,

    sheet_name:
      sheetName
  }
}];

// ============================================
// n8n CODE NODE
// Parse AI JSON Response
// ============================================

// Get raw AI response
const raw =
  $input.first().json.content[0].text;

// Remove markdown wrappers
const cleaned = raw
  .replace(/```json/g, '')
  .replace(/```/g, '')
  .trim();

// Parse JSON array
const data = JSON.parse(cleaned);

// Return each employee as separate item
return data.map(employeeData => {
  return {
    json: employeeData
  };
});

// INPUTS
const empEstimateData = $input.first().json.emp_estimate_data;

// EMPLOYEE -> TASK TYPE MAP
const employeeTaskMap = {
  "Jon and Christian": ["CRPA"],
  "Sarah": ["SCOP"],
  "Cal": ["ADRI"],
  "Nick": ["HODE"],
  "Mavis": ["MODE", "EXMO"],
  "Lauren":["COPY"],
  "Dani": ["SNDE", "EXSD"]
};

const results = [];

// LOOP THROUGH EMPLOYEE MAP
for (const [employeeName, mappedTaskTypes] of Object.entries(employeeTaskMap)) {

  // MATCH ESTIMATE ROWS
  const matchedEstimates = empEstimateData.filter(est =>
    mappedTaskTypes.includes(est["Task Type Code"])
  );

  // CREATE OUTPUT
  for (const estimate of matchedEstimates) {

    results.push({
      "employee": employeeName,
      "Job No.": estimate["Job Number"],
      "Job Description": estimate["Job Description"],
      "taskTypes": estimate["Task Type Code"],
      "task_description": estimate["Description"],
      "Units": estimate["Units"]
    });

  }
}

return results.map(item => ({ json: item }));

// ============================================
// n8n CODE NODE
// Multi Employee Allocation Engine
// With Proper Conflict Detection
// ============================================

// ============================================
// SAFE HELPERS
// ============================================

function safeNumber(value) {

  const num = parseFloat(value);

  return Number.isFinite(num)
    ? num
    : 0;
}

function safeArray(value) {

  return Array.isArray(value)
    ? value
    : [];
}

function safeString(value) {

  if (
    value === null ||
    value === undefined
  ) {
    return "";
  }

  return String(value).trim();
}

// ============================================
// CONFIG
// ============================================

// weekly overload threshold
const MAX_HOURS_PER_WEEK = 40;

// ============================================
// INPUTS
// ============================================

// employee free hour data
const employeeFreeHours =
  safeArray(
    $('Aggregate2')
      .first()
      .json
      .employee_free_hour_data
  );

// employee task assignment data
const estimateData =
  safeArray(
    $('Aggregate3')
      .first()
      .json["Employee Tasktype Data"]
  );

// project timeline
const timeline =
  $input.first()
    ?.json
    ?.project_timeline || {};

// ============================================
// VALIDATE TIMELINE
// ============================================

if (
  !timeline.start_date ||
  !timeline.end_date
) {

  throw new Error(
    'Missing project timeline dates'
  );
}

// ============================================
// TIMELINE DATES
// ============================================

const timelineStart =
  new Date(timeline.start_date);

const timelineEnd =
  new Date(timeline.end_date);

timelineStart.setHours(0,0,0,0);
timelineEnd.setHours(0,0,0,0);

// ============================================
// FORMAT DATE
// ============================================

function formatTimelineDate(dateStr) {

  const date =
    new Date(dateStr);

  return date.toLocaleDateString(
    'en-US',
    {
      month: 'short',
      day: 'numeric'
    }
  );
}

// ============================================
// PARSE SHEET DATE
// ============================================

function parseSheetDate(dateStr) {

  if (!dateStr) {
    return null;
  }

  const cleanDate =
    safeString(dateStr);

  const year =
    timelineStart.getFullYear();

  const parsed =
    new Date(`${cleanDate} ${year}`);

  if (
    isNaN(parsed.getTime())
  ) {
    return null;
  }

  parsed.setHours(0,0,0,0);

  return parsed;
}

// ============================================
// GET WEEK KEY
// ============================================

function getWeekKey(dateObj) {

  const date =
    new Date(dateObj);

  const firstDay =
    new Date(date);

  firstDay.setDate(
    date.getDate() - date.getDay()
  );

  firstDay.setHours(0,0,0,0);

  return firstDay
    .toISOString()
    .split('T')[0];
}

// ============================================
// GROUP TASKS BY EMPLOYEE
// ============================================

const employeeTaskMap = {};

for (const item of estimateData) {

  const employee =
    safeString(item.employee);

  if (!employee) {
    continue;
  }

  if (!employeeTaskMap[employee]) {

    employeeTaskMap[employee] = [];
  }

  employeeTaskMap[employee]
    .push(item);
}

// ============================================
// PROCESS EMPLOYEES
// ============================================

const results = [];

for (const employeeFree of employeeFreeHours) {

  // ==========================================
  // EMPLOYEE
  // ==========================================

  const employeeName =
    safeString(
      employeeFree.employee
    );

  if (!employeeName) {
    continue;
  }

  // ==========================================
  // FREE TIME
  // ==========================================

  const freeTime =
    safeArray(
      employeeFree.free_time
    );

  // ==========================================
  // EMPLOYEE TASKS
  // ==========================================

  const employeeTasks =
    employeeTaskMap[
      employeeName
    ] || [];

  const assignedToProject =
    employeeTasks.length > 0;

  // ==========================================
  // NOT ASSIGNED
  // ==========================================

  if (!assignedToProject) {

    results.push({

      employee:
        employeeName,

      assigned_to_project:
        false,

      total_allocated_hours:
        0

    });

    continue;
  }

  // ==========================================
  // REQUIRED HOURS
  // ==========================================

  const totalRequiredHours =
    employeeTasks.reduce(
      (sum, item) =>
        sum +
        safeNumber(item.Units),
      0
    );

  // ==========================================
  // JOB INFO
  // ==========================================

  const firstTask =
    employeeTasks[0] || {};

  const jobNo =
    safeString(
      firstTask["Job No."]
    );

  const jobDescription =
    safeString(
      firstTask["Job Description"]
    );

  const taskType =
    safeString(
      firstTask.taskTypes
    );

  // ==========================================
  // SORT FREE TIME
  // ==========================================

  const sortedFreeTime =
    [...freeTime].sort((a, b) => {

      const dateA =
        parseSheetDate(a.date);

      const dateB =
        parseSheetDate(b.date);

      return dateA - dateB;
    });

  // ==========================================
  // ALLOCATION ENGINE
  // ==========================================

  let remainingHours =
    totalRequiredHours;

  const allocations = [];

  const weeklyExistingHours = {};
  const weeklyNewHours = {};

  // ==========================================
  // PROCESS DAYS
  // ==========================================

  for (const day of sortedFreeTime) {

    const sheetDate =
      parseSheetDate(day.date);

    if (!sheetDate) {
      continue;
    }

    // only inside project timeline
    if (
      sheetDate < timelineStart ||
      sheetDate > timelineEnd
    ) {
      continue;
    }

    const freeHours =
      safeNumber(
        day.free_hours
      );

    // ======================================
    // WEEK KEY
    // ======================================

    const weekKey =
      getWeekKey(sheetDate);

    if (
      !weeklyExistingHours[weekKey]
    ) {

      weeklyExistingHours[
        weekKey
      ] = 0;
    }

    if (
      !weeklyNewHours[weekKey]
    ) {

      weeklyNewHours[
        weekKey
      ] = 0;
    }

    // ======================================
    // EXISTING HOURS
    // ======================================

    const existingHours =
      8 - freeHours;

    weeklyExistingHours[
      weekKey
    ] += existingHours;

    // ======================================
    // SKIP IF NO REMAINING
    // ======================================

    if (remainingHours <= 0) {
      continue;
    }

    // ======================================
    // SKIP FULLY OCCUPIED DAY
    // ======================================

    if (freeHours <= 0) {
      continue;
    }

    // ======================================
    // ALLOCATE HOURS
    // ======================================

    const allocatedHours =
      Math.min(
        freeHours,
        remainingHours
      );

    weeklyNewHours[
      weekKey
    ] += allocatedHours;

    allocations.push({

      employee:
        employeeName,

      task_type:
        taskType,

      date:
        safeString(day.date),

      allocated_hours:
        Number(
          allocatedHours.toFixed(2)
        ),

      remaining_free_hours:
        Number(
          (
            freeHours -
            allocatedHours
          ).toFixed(2)
        )

    });

    // reduce remaining
    remainingHours =
      Number(
        (
          remainingHours -
          allocatedHours
        ).toFixed(2)
      );
  }

  // ==========================================
  // TOTAL ALLOCATED
  // ==========================================

  const totalAllocatedHours =
    Number(
      (
        totalRequiredHours -
        remainingHours
      ).toFixed(2)
    );

  // ==========================================
  // CONFLICT DETECTION
  // ==========================================

  let conflict = false;

  const conflictTypes = [];

  const conflictDetails = [];

  // ==========================================
  // CONFLICT 1
  // CAPACITY CONFLICT
  // ==========================================

  if (remainingHours > 0) {

    conflict = true;

    conflictTypes.push(
      'capacity_conflict'
    );

    conflictDetails.push({

      employee:
        employeeName,

      issue:
        'Insufficient free hours inside timeline',

      required_hours:
        totalRequiredHours,

      allocated_hours:
        totalAllocatedHours,

      unallocated_hours:
        Number(
          remainingHours.toFixed(2)
        )

    });
  }

  // ==========================================
  // CONFLICT 2
  // WEEKLY OVERLOAD
  // ==========================================

  for (const weekKey in weeklyNewHours) {

    const existingHours =
      weeklyExistingHours[
        weekKey
      ] || 0;

    const newHours =
      weeklyNewHours[
        weekKey
      ] || 0;

    const totalWeekHours =
      existingHours +
      newHours;

    if (
      totalWeekHours >
      MAX_HOURS_PER_WEEK
    ) {

      conflict = true;

      if (
        !conflictTypes.includes(
          'weekly_overload'
        )
      ) {

        conflictTypes.push(
          'weekly_overload'
        );
      }

      conflictDetails.push({

        employee:
          employeeName,

        week:
          weekKey,

        existing_hours:
          Number(
            existingHours.toFixed(2)
          ),

        new_hours:
          Number(
            newHours.toFixed(2)
          ),

        total_hours:
          Number(
            totalWeekHours.toFixed(2)
          ),

        max_allowed_hours:
          MAX_HOURS_PER_WEEK,

        overload_hours:
          Number(
            (
              totalWeekHours -
              MAX_HOURS_PER_WEEK
            ).toFixed(2)
          )

      });
    }
  }

  // ==========================================
  // FINAL RESULT
  // ==========================================

  results.push({

    employee:
      employeeName,

    assigned_to_project:
      true,

    task_type:
      taskType,

    job_no:
      jobNo,

    job_description:
      jobDescription,

    total_required_hours:
      Number(
        totalRequiredHours.toFixed(2)
      ),

    total_allocated_hours:
      totalAllocatedHours,

    unallocated_hours:
      Number(
        remainingHours.toFixed(2)
      ),

    project_start_date:
      formatTimelineDate(
        timeline.start_date
      ),

    project_end_date:
      formatTimelineDate(
        timeline.end_date
      ),

    // ======================================
    // CONFLICTS
    // ======================================

    conflict,

    conflict_types:
      conflictTypes,

    conflict_details:
      conflictDetails,

    allow_auto_population:
      conflict === false,

    requires_manual_review:
      conflict === true,

    allocations

  });
}

// ============================================
// OUTPUT
// ============================================

return results.map(item => ({
  json: item
}));

// ============================================
// n8n CODE NODE
// Find Correct Insert Row For Assigned Employees
// ============================================

// ============================================
// INPUTS
// ============================================

// full sheet data
const rows =
$input.first().json.data || [];

// assigned employee allocation data
const employeeProjects =
  $('Aggregate4')
    .first()
    ?.json
    ?.Employees_New_Project_Hours || [];

// ============================================
// CONFIG
// ============================================

const TOTAL_HOURS_LABEL =
  'total hours per day';

// ============================================
// SAFE HELPERS
// ============================================

function safeString(value) {

  if (
    value === null ||
    value === undefined
  ) {
    return '';
  }

  return String(value).trim();
}

function safeNumber(value) {

  const num = parseFloat(value);

  return Number.isFinite(num)
    ? num
    : 0;
}

// ============================================
// GET ALL DATE COLUMNS
// ============================================

const dateColumns =
  Object.keys(rows[0] || {})
    .filter(key =>
      /^col_\d+$/.test(key)
    )
    .sort((a, b) => {

      const aNum =
        Number(a.replace('col_', ''));

      const bNum =
        Number(b.replace('col_', ''));

      return aNum - bNum;
    });

// ============================================
// RESULTS
// ============================================

const results = [];

// ============================================
// PROCESS EMPLOYEES
// ============================================

for (const employeeData of employeeProjects) {

  // only assigned employees
  if (
    employeeData.assigned_to_project !== true
  ) {
    continue;
  }

  const employeeName =
    safeString(
      employeeData.employee
    );

  if (!employeeName) {
    continue;
  }

  // ==========================================
  // FIND EMPLOYEE SECTION
  // ==========================================

  let employeeRowIndex = -1;
  let totalHoursRowIndex = -1;

  for (let i = 0; i < rows.length; i++) {

    const briefing =
      safeString(
        rows[i]?.Briefing
      ).toLowerCase();

    // employee header row
    if (
      briefing ===
      employeeName.toLowerCase()
    ) {

      employeeRowIndex = i;

      // find next "Total hours per day"
      for (
        let j = i + 1;
        j < rows.length;
        j++
      ) {

        const nextBriefing =
          safeString(
            rows[j]?.Briefing
          ).toLowerCase();

        if (
          nextBriefing ===
          TOTAL_HOURS_LABEL
        ) {

          totalHoursRowIndex = j;
          break;
        }
      }

      break;
    }
  }

  // ==========================================
  // SKIP INVALID EMPLOYEE SECTION
  // ==========================================

  if (
    employeeRowIndex === -1
  ) {

    results.push({

      employee:
        employeeName,

      employee_name_row:
        employeeRowIndex,

      insert_row_number:
        null,

      error:
        'Employee section not found'

    });

    continue;
  }

  // ==========================================
  // DEFAULT INSERT POSITION
  // BEFORE TOTAL HOURS ROW
  // ==========================================

  let insertRowNumber =
    safeNumber(
      rows[
        totalHoursRowIndex-1
      ]?.row_number
    );

  // ==========================================
  // FIND LAST PROJECT ROW
  // ==========================================

  for (
    let i = employeeRowIndex + 1;
    i < totalHoursRowIndex;
    i++
  ) {

    const row = rows[i];

    const briefing =
      safeString(
        row?.Briefing
      );

    // skip empty rows
    if (!briefing) {
      continue;
    }

    // skip total row
    if (
      briefing.toLowerCase() ===
      TOTAL_HOURS_LABEL
    ) {
      continue;
    }

    // ======================================
    // CHECK IF ROW HAS HOURS
    // ======================================

    let hasHours = false;

    for (const col of dateColumns) {

      const value = row[col];

      if (

        value !== '' &&
        value !== null &&
        value !== undefined &&
        safeNumber(value) > 0

      ) {

        hasHours = true;
        break;
      }
    }

    // ======================================
    // UPDATE INSERT POSITION
    // ======================================

    if (hasHours) {

      insertRowNumber =
        safeNumber(
          row.row_number
        ) + 1;
    }
  }

  // ==========================================
  // OUTPUT
  // ==========================================

  results.push({

    employee:
      employeeName,

    insert_row_number:
      insertRowNumber

  });
}

// ============================================
// FINAL OUTPUT
// ============================================

return results.map(item => ({
  json: item
}));

// ============================================
// n8n CODE NODE
// Create Sheet Row Values
// For ALL Assigned Employees
// ============================================

// ============================================
// INPUTS
// ============================================

const sheetData =
  $('Aggregate5')
    .first()
    .json
    .updated_sheet_data || [];

const employeeFreeHours =
  $('Aggregate2')
    .first()
    .json
    .employee_free_hour_data || [];

const projectData =
  $('Aggregate4')
    .first()
    .json
    .Employees_New_Project_Hours || [];

// ============================================
// SAFE HELPERS
// ============================================

function safeString(value) {

  if (
    value === null ||
    value === undefined
  ) {
    return '';
  }

  return String(value).trim();
}

function safeNumber(value) {

  const num =
    parseFloat(value);

  return Number.isFinite(num)
    ? num
    : 0;
}

function safeArray(value) {

  return Array.isArray(value)
    ? value
    : [];
}

// ============================================
// FIND DATE HEADER ROW
// Usually row 8
// ============================================

let dateHeaderRow = null;

for (const row of sheetData) {

  const col3 =
    row.col_3;

  if (

    col3 !== '' &&
    col3 !== null &&
    col3 !== undefined &&
    !isNaN(Number(col3))

  ) {

    dateHeaderRow = row;
    break;
  }
}

if (!dateHeaderRow) {

  throw new Error(
    'Date header row not found'
  );
}

// ============================================
// GET ALL DATE COLUMNS
// ============================================

const dateColumns = [];

for (let col = 3; col <= 25; col++) {

  const value =
    dateHeaderRow[`col_${col}`];

  if (

    value !== '' &&
    value !== null &&
    value !== undefined

  ) {

    dateColumns.push({

      colKey:
        `col_${col}`,

      day:
        Number(value)

    });
  }
}

// ============================================
// RESULTS
// ============================================

const results = [];

// ============================================
// PROCESS ALL EMPLOYEES
// ============================================

for (const project of projectData) {

  // only assigned employees
  if (
    project.assigned_to_project !== true
  ) {
    continue;
  }

  const employee =
    safeString(
      project.employee
    );

  if (!employee) {
    continue;
  }

  // ==========================================
  // EMPLOYEE FREE TIME
  // ==========================================

  const employeeFree =
    employeeFreeHours.find(
      emp =>
        safeString(emp.employee)
          .toLowerCase()
        ===
        employee.toLowerCase()
    );

  const freeTime =
    safeArray(
      employeeFree?.free_time
    );

  // ==========================================
  // PROJECT INFO
  // ==========================================

  const jobNo =
    safeString(
      project.job_no
    );

  const jobDescription =
    safeString(
      project.job_description
    );

  const totalAllocatedHours =
    safeNumber(
      project.total_allocated_hours
    );

  const projectStartDate =
    safeString(
      project.project_start_date
    );

  const projectEndDate =
    safeString(
      project.project_end_date
    );

  const allocations =
    safeArray(
      project.allocations
    );

  // ==========================================
  // CREATE ALLOCATION MAP
  // ==========================================

  const allocationMap = {};

  for (const allocation of allocations) {

    const date =
      safeString(
        allocation.date
      );

    allocationMap[date] =
      safeNumber(
        allocation.allocated_hours
      );
  }

  // ==========================================
  // CREATE ROW VALUES
  // ==========================================

  const rowValues = [];

  // Column A → Project Name
  rowValues.push(
    `${jobNo} ${jobDescription}`.trim()
  );

  // Column B → Always "All"
  rowValues.push('All');

  // ==========================================
  // BUILD DATE COLUMNS
  // ==========================================

  for (const dateCol of dateColumns) {

    const matchingFreeDay =
      freeTime.find(day => {

        const dayDate =
          safeString(day.date);

        // extract numeric day
        const split =
          dayDate.split(' ');

        const numericDay =
          Number(split[1]);

        return (
          numericDay ===
          dateCol.day
        );
      });

    // no matching date
    if (!matchingFreeDay) {

      rowValues.push('');
      continue;
    }

    const fullDate =
      safeString(
        matchingFreeDay.date
      );

    const allocatedHours =
      allocationMap[fullDate];

