function safeNumber(value) {

  const num = Number(value);

  return Number.isFinite(num)
    ? num
    : 0;
}

function formatMoney(value) {

  return safeNumber(value)
    .toFixed(2);
}

function calculateTotal(item) {

  const units =
    safeNumber(item.units);

  const rate =
    safeNumber(item.rate);

  const markUp =
    safeNumber(item.markUp);

  const serviceFee =
    safeNumber(item.serviceFee);

  const tax =
    safeNumber(item.tax);

  return (
    (units * rate) +
    markUp +
    serviceFee +
    tax
  );
}

