    .Employees_New_Project_Hours || [];

// ============================================
// HELPERS
// ============================================

function safeString(value) {

  if (
    value === null ||
    value === undefined
  ) {
    return '';
  }

  return String(value).trim();
}

const TOTAL_LABEL =
  'total hours per day';

// ============================================
// RESULTS
// ============================================

const results = [];

// ============================================
// PROCESS EACH EMPLOYEE
// ============================================

for (const emp of employeeProjects) {

  // ONLY ASSIGNED EMPLOYEES
  if (
    emp.assigned_to_project !== true
  ) {
    continue;
  }

  const employeeName =
    safeString(emp.employee);

  if (!employeeName) {
    continue;
  }

  // ==========================================
  // FIND EMPLOYEE ROW + TOTAL HOURS ROW
  // ==========================================

  let employeeRowIndex = -1;
  let totalHoursRowIndex = -1;

  for (let i = 0; i < rows.length; i++) {

    const briefing =
      safeString(
        rows[i].Briefing
      ).toLowerCase();

    // EMPLOYEE ROW
    if (
      briefing ===
      employeeName.toLowerCase()
    ) {

      employeeRowIndex = i;
    }

    // TOTAL HOURS ROW
    if (
      briefing === TOTAL_LABEL
    ) {

      // only take total row AFTER employee row
      if (
        employeeRowIndex !== -1 &&
        i > employeeRowIndex
      ) {

        totalHoursRowIndex = i;
        break;
      }
    }
  }

  // ==========================================
  // SAFETY CHECKS
  // ==========================================

  if (employeeRowIndex === -1) {

    results.push({
      employee: employeeName,
      insert_row_number: null,
      error: 'Employee row not found'
    });

    continue;
  }

  if (totalHoursRowIndex === -1) {

    results.push({
      employee: employeeName,
      insert_row_number: null,
      error: 'Total hours row not found'
    });

    continue;
  }

  // ==========================================
  // FIND LAST PROJECT ROW
  // ==========================================

  let insertRowNumber =
    rows[totalHoursRowIndex]
      .row_number;

  for (
    let i = employeeRowIndex + 1;
    i < totalHoursRowIndex;
    i++
  ) {

    const row = rows[i];

    const briefing =
      safeString(row.Briefing);

    // SKIP EMPTY ROWS
    if (!briefing) {
      continue;
    }

    // SKIP TOTAL ROW
    if (
      briefing.toLowerCase() ===
      TOTAL_LABEL
    ) {
      continue;
    }

    // ========================================
    // DETECT PROJECT HOURS
    // ========================================

    let hasHours = false;

    for (
      let col = 3;
      col <= 24;
      col++
    ) {

      const value =
        row[`col_${col}`];

      if (
        value !== '' &&
        value !== null &&
        value !== undefined &&
        Number(value) > 0
      ) {

        hasHours = true;
        break;
      }
    }

    // ========================================
    // UPDATE INSERT POSITION
    // ========================================

    if (hasHours) {

      insertRowNumber =
        row.row_number + 1;
    }
  }

  // ==========================================
  // OUTPUT
  // ==========================================

  results.push({

    employee: employeeName,

    insert_row_number:
      insertRowNumber

  });
}

