// Generate Month Start & End Date
// From sheet_name like: "June 26"
// ============================================

// ============================================
// INPUT
// ============================================

const sheetName =
  $('Code in JavaScript')
    .first()
    .json
    .sheet_name || '';

// ============================================
// VALIDATION
// ============================================

if (
  !sheetName ||
  typeof sheetName !== 'string'
) {

  return [{
    json: {
      error: 'sheet_name missing or invalid'
    }
  }];
}

// ============================================
// PARSE MONTH + YEAR
// ============================================

const parts = sheetName.trim().split(' ');

if (parts.length !== 2) {

  return [{
    json: {
      error: 'Invalid sheet_name format',
      expected: 'Month YY',
      received: sheetName
    }
  }];
}

const monthName = parts[0];
const shortYear = parts[1];

// Convert YY → YYYY
const year = Number(`20${shortYear}`);

// Month mapping
const months = {
  january: 0,
  february: 1,
  march: 2,
  april: 3,
  may: 4,
  june: 5,
  july: 6,
  august: 7,
  september: 8,
  october: 9,
  november: 10,
  december: 11
};

const monthIndex =
  months[monthName.toLowerCase()];

if (monthIndex === undefined) {

  return [{
    json: {
      error: 'Invalid month name',
      received: monthName
    }
  }];
}

// ============================================
// CALCULATE DATES
// ============================================

// First day of month
const start = new Date(year, monthIndex, 1);

// Last day of month
const end = new Date(year, monthIndex + 1, 0);

// Format YYYY-MM-DD
const formatDate = (date) => {

  const y = date.getFullYear();

  const m = String(
    date.getMonth() + 1
  ).padStart(2, '0');

  const d = String(
    date.getDate()
  ).padStart(2, '0');

  return `${y}-${m}-${d}`;
};

const startDate = formatDate(start);
const endDate = formatDate(end);

// ============================================
// CALCULATE DAYS
// ============================================

const diffTime =
  end.getTime() - start.getTime();

const daysAllocated =
  Math.floor(
    diffTime / (1000 * 60 * 60 * 24)
  ) + 1;

// ============================================
// OUTPUT
// ============================================

return [{
  json: {
    project_timeline: {
      milestone_name: "Production",

      start_date: startDate,

      end_date: endDate,

      days_allocated: daysAllocated
    }
  }
}];

